// Regression: UCOMISD sets ZF for both equality and unordered operands.
// NaN arithmetic must stay a float in scalar, fused and counted-loop paths.
#if TARGET_OS == "windows"
extern function nativeSqrt(value as double) from "msvcrt.dll" symbol "sqrt" returns double
#else
extern function nativeSqrt(value as double) from "libm.so.6" symbol "sqrt" returns double
#endif

failures = 0
function check(value, label)
  global failures
  if not value then
    failures = failures + 1
    print "[FAIL] " + label
  end if
end function
function isNaN(value)
  return typeof(value) == "float" and value != value
end function
function genericAdd(a, b) return a + b end function
function genericSub(a, b) return a - b end function
function genericMul(a, b) return a * b end function
function genericDiv(a, b) return a / b end function
function genericMod(a, b) return a % b end function
function typedTree(a as float, b as float)
  return (a - b) * 0.25 + 0.125
end function
function typedLoop(n as int, x as float, y as float)
  i as int = 0
  while i < n
    x = (x + y) * 0.25 + 0.125
    i = i + 1
  end while
  return [x, i]
end function
function foldedNaN() return (.0 - .0) + 0.5 end function
function foldedNegativeNaN() return -(.0 - .0) end function
function foldedProductNaN() return (.0 - .0) * 0.5 end function
function foldedQuotientNaN() return (.0 - .0) / 2.0 end function
function foldedUnorderedDivisor() return 2.0 / (.0 - .0) end function
function main(args)
  global failures
  check(isNaN(foldedNaN()), "constant-folded NaN addition")
  check(isNaN(foldedNegativeNaN()), "constant-folded NaN negation")
  check(isNaN(foldedProductNaN()), "constant-folded NaN multiplication")
  check(isNaN(foldedQuotientNaN()), "constant-folded NaN division")
  check(typeof(foldedUnorderedDivisor()) == "void", "constant unordered divisor keeps runtime contract")
  immediateNaN = nativeValueFromRaw((2143289344 << 3) | 5)
  nativeNaN = nativeSqrt(-1.0)
  infinity = nativeValueFromRaw((2139095040 << 3) | 5)
  negativeInfinity = nativeValueFromRaw((4286578688 << 3) | 5)
  for each value in [immediateNaN, nativeNaN]
    check(isNaN(value), "input NaN")
    check(isNaN(genericAdd(value, 1.0)), "scalar addition")
    check(isNaN(genericSub(value, 1.0)), "scalar subtraction")
    check(isNaN(genericMul(value, 0.0)), "scalar multiplication")
    check(isNaN(genericDiv(value, 2.0)), "scalar division")
    check(isNaN(genericMod(value, 2.0)), "scalar modulo")
    check(isNaN(typedTree(value, 0.25)), "fused tree")
    state = typedLoop(3, value, 0.25)
    check(isNaN(state[0]) and state[1] == 3, "counted loop")
  end for
  check(isNaN(genericSub(infinity, infinity)), "new NaN from subtraction")
  check(isNaN(genericAdd(infinity, negativeInfinity)), "new NaN from addition")
  check(isNaN(typedTree(infinity, infinity)), "new NaN inside fused tree")
  state = typedLoop(2, infinity, negativeInfinity)
  check(isNaN(state[0]) and state[1] == 2, "new NaN inside counted loop")
  check(genericAdd(infinity, 1.0) == infinity, "positive infinity preserved")
  check(genericSub(negativeInfinity, 1.0) == negativeInfinity, "negative infinity preserved")
  exact = genericAdd(0.25, 0.75)
  check(typeof(exact) == "int" and exact == 1, "exact integers still normalize")
  negativeZero = nativeValueFromRaw((2147483648 << 3) | 5)
  zero = genericAdd(negativeZero, 0.0)
  check(typeof(zero) == "int" and zero == 0, "zero keeps integer normalization")
  large = nativeValueFromRaw((1577058304 << 3) | 5)
  check(genericAdd(large, 0.0) == 0, "signed61 wrap preserved")
  if failures != 0 then return 1 end if
  print "NUMERIC NAN NORMALIZATION [OK]"
  return 0
end function
